import { defineComponent } from "../../lib/ecs-js/index.js";
/**
 * ItemInfo — rules-side description of an item.
 * Used for inventory logic, weight calculations, equipment slots, etc.
 * No display names, glyphs, or color info.
 */
export const ItemInfo = defineComponent(
  "ItemInfo",
  {
    type: "", // logical category, e.g. "weapon", "potion", "scroll"
    slot: "", // intended equipment or container slot, e.g. "hand", "bag"
    weight: 0, // numeric weight (for encumbrance or turn cost)
    value: 0, // optional numeric value for trade/scoring
    description: "", // flavor text description of the item
    count: 1, // stacking count; >=1 for any item entity
    bonuses: {}, // flat bonuses: { attack, defense, maxHp, critChance, critMult, ... }
    twoHanded: false, // requires both hands; blocks offhand slot
    rarity: 1,
    rarityName: "common",
    // Legacy compatibility arrays. Runtime affixes/enchantments/sockets should
    // prefer attached topology nodes; see RUNTIME_TOPOLOGY_DOCTRINE.md.
    affixes: [], // list of affix ids applied to this item (rules/data/affixes)
    sockets: [], // gem ids socketed into this item (e.g. ['gem_ruby'])
    maxSockets: 0, // maximum number of gem sockets this item can hold
    weaponLengthCm: null, // physical weapon length in centimeters (rules -> display)
    weaponVfxProfile: null, // density profile key (grip->tip) for weapon VFX
    weaponFamily: "", // semantic weapon family for combat/audio affordances
    noQuickChip: false, // suppress pickup quick-chip UI for this item
    tags: [], // behavioral flags: "conflict", "sunlight", "levitate", etc.
    ammoAffinities: {}, // ammo identity -> projectile modifiers from this gear
    lootBiases: {}, // loot/archetype id -> weight multiplier while equipped
  },
  {
    validate(rec) {
      if (typeof rec.type !== "string")
        throw new Error("ItemInfo.validate(): type must be a string");
      if (typeof rec.slot !== "string")
        throw new Error("ItemInfo.validate(): slot must be a string");
      if (typeof rec.weight !== "number" || rec.weight < 0)
        throw new Error(
          "ItemInfo.validate(): weight must be a non-negative number"
        );
      if (typeof rec.value !== "number" || rec.value < 0)
        throw new Error(
          "ItemInfo.validate(): value must be a non-negative number"
        );
      if (typeof rec.description !== "string")
        throw new Error("ItemInfo.validate(): description must be a string");
      if (!Number.isFinite(rec.count) || rec.count < 1)
        throw new Error("ItemInfo.validate(): count must be >= 1");
      if (rec.bonuses && typeof rec.bonuses !== 'object')
        throw new Error("ItemInfo.validate(): bonuses must be an object");
      if (!Number.isFinite(rec.rarity) || rec.rarity < 1)
        throw new Error("ItemInfo.validate(): rarity must be >= 1");
      if (typeof rec.rarityName !== 'string')
        throw new Error("ItemInfo.validate(): rarityName must be a string");
      if (!Array.isArray(rec.affixes))
        throw new Error("ItemInfo.validate(): affixes must be an array");
      if (typeof rec.noQuickChip !== "boolean")
        throw new Error("ItemInfo.validate(): noQuickChip must be a boolean");
      if (!Array.isArray(rec.tags))
        throw new Error("ItemInfo.validate(): tags must be an array");
      if (!rec.ammoAffinities || typeof rec.ammoAffinities !== 'object' || Array.isArray(rec.ammoAffinities))
        throw new Error("ItemInfo.validate(): ammoAffinities must be an object");
      if (!rec.lootBiases || typeof rec.lootBiases !== 'object' || Array.isArray(rec.lootBiases))
        throw new Error("ItemInfo.validate(): lootBiases must be an object");
      if (rec.weaponLengthCm != null && (!Number.isFinite(rec.weaponLengthCm) || rec.weaponLengthCm <= 0))
        throw new Error("ItemInfo.validate(): weaponLengthCm must be null or a positive number");
      if (rec.weaponVfxProfile != null && typeof rec.weaponVfxProfile !== "string" && typeof rec.weaponVfxProfile !== "object")
        throw new Error("ItemInfo.validate(): weaponVfxProfile must be null, string, or object");
      if (typeof rec.weaponFamily !== "string")
        throw new Error("ItemInfo.validate(): weaponFamily must be a string");
      return true;
    },
  }
);
// rules/utils/itemFactory.js
// Centralized item creation by ID. Single source of truth for spawning items.

import { createFrom } from '../../lib/ecs-js/archetype.js';
import { buildCatalogItem } from '../data/itemCatalogLoader.js';
import { ITEM_CATALOG, getCatalogItem } from '../data/itemCatalog.js';
import * as gems from '../data/gems.js';
import { ItemInfo } from '../components/ItemInfo.js';

// Archetypes
import { GoldStack, HealthPotion, ArrowsStack, FireArrowsStack, PiercingArrowsStack, BodkinArrowsStack, BluntHeadArrowsStack, ChalkArrowsStack, BombArrowsStack, ScrollOfMapping, GemItem, Bone } from '../archetypes/Items.js';
import {
  Ration, IronRation, WildBerries, WildHerbs,
  DungeonMushrooms, Wheat, Carrot, Corn,
} from '../archetypes/Food.js';

let _SIMPLE_ITEM_ARCHETYPES = null;

/**
 * Centralized item creation registry.
 * Maps item identity strings to their archetype constructors.
 * Lazily built so circular import paths can load Food.js before reading
 * Food archetype bindings.
 */
function simpleItemArchetypes() {
  if (_SIMPLE_ITEM_ARCHETYPES) return _SIMPLE_ITEM_ARCHETYPES;
  _SIMPLE_ITEM_ARCHETYPES = {
    'gold': GoldStack,
    'potion_health': HealthPotion,
    'ammo_arrows': ArrowsStack,
    'ammo_fire_arrows': FireArrowsStack,
    'ammo_piercing_arrows': PiercingArrowsStack,
    'ammo_bodkin_arrows': BodkinArrowsStack,
    'ammo_blunt_arrows': BluntHeadArrowsStack,
    'ammo_chalk_arrows': ChalkArrowsStack,
    'ammo_bomb_arrows': BombArrowsStack,
    'scroll_mapping': ScrollOfMapping,
    'bone': Bone,
    'food_ration': Ration,
    'food_iron_ration': IronRation,
    'food_wild_berries': WildBerries,
    'food_wild_herbs': WildHerbs,
    'food_mushrooms': DungeonMushrooms,
    'food_wheat': Wheat,
    'food_carrot': Carrot,
    'food_corn': Corn,
  };
  return _SIMPLE_ITEM_ARCHETYPES;
}

/**
 * Create an item entity by its ID string.
 * Does NOT add Position - caller should place the item if needed.
 *
 * @param {import('../../lib/ecs-js/index.js').World} world - ECS world
 * @param {string} itemId - Item identifier (e.g., 'gold', 'sword_plain', 'book_lightning')
 * @param {Object} opts - Options
 * @param {number} [opts.count] - Optional explicit stack count override
 * @param {string[]} [opts.affixes=[]] - Affix IDs for equipment
 * @returns {number|null} - Created entity ID, or null if unknown item
 */
export function createItemById(world, itemId, opts = {}) {
  const rawCount = Number(opts?.count);
  const hasExplicitCount = Number.isFinite(rawCount) && rawCount > 0;
  const count = hasExplicitCount ? (rawCount | 0) : 0;
  const affixes = opts.affixes || [];

  // 1. Check simple archetypes (gold, potions, food, ammo, etc.)
  const simple = simpleItemArchetypes();
  if (simple[itemId]) {
    const id = createFrom(world, simple[itemId], {});
    // Set count for stackable items
    if (count > 1) {
      world.mutate(id, ItemInfo, r => { r.count = count; });
    }
    return id;
  }

  // 2. Check unified catalog definitions
  const catalogDef = getCatalogItem(itemId);
  if (catalogDef) {
    const buildOpts = { affixes };
    if (hasExplicitCount) buildOpts.count = count;
    return buildCatalogItem(world, itemId, buildOpts);
  }

  // 3. Check gem definitions
    const gemDef = gems.getGem(itemId);
  if (gemDef) {
    const params = gems.buildGemItemParams(gemDef);
    if (!params) return null;
    const id = createFrom(world, GemItem, params);
    return id;
  }

  // Unknown item
  return null;
}

/**
 * Check if an item ID is valid and can be created.
 * @param {string} itemId
 * @returns {boolean}
 */
export function isValidItemId(itemId) {
  return !!(
    simpleItemArchetypes()[itemId] ||
    getCatalogItem(itemId) ||
    gems.getGem(itemId)
  );
}

/**
 * Get all valid item IDs.
 * @returns {string[]}
 */
export function listAllItemIds() {
  const simpleIds = Object.keys(simpleItemArchetypes());
  const catalogIds = Object.keys(ITEM_CATALOG || {});
  const gemIds = gems.listGemIds();
  return Array.from(new Set([...simpleIds, ...catalogIds, ...gemIds]));
}

